28: function showToast(text) {
29:   toast.textContent = text;
30:   toast.classList.add('show');
31:   clearTimeout(toastTimer);
32:   toastTimer = setTimeout(() => toast.classList.remove('show'), 2300);
33: }
34: function escapeHTML(text) {
35:   return text.replace(/[&<>"']/g, (char) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
36: }
37: function timeNow() {
38:   return new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());
39: }
40: function appendMessage(text, who) {
41:   const row = document.createElement('div');
42:   row.className = `message-row ${who === 'user' ? 'user-row' : 'assistant-row'}`;
43:   const safe = escapeHTML(text).replace(/\n/g,'<br>');
44:   row.innerHTML = `${who === 'assistant' ? '<span class="message-avatar">m</span>' : ''}<div class="message-content"><span class="message-author">${who === 'assistant' ? 'Mori' : '小满'} <time>${timeNow()}</time></span><div class="bubble">${safe}</div>${who === 'assistant' ? '<div class="message-reactions"><button class="reaction" aria-label="喜欢">♡</button><button class="reaction" aria-label="复制">▢</button></div>' : ''}</div>${who === 'user' ? '<span class="message-avatar">林</span>' : ''}`;
45:   messages.appendChild(row);
46:   messages.scrollTop = messages.scrollHeight;
47:   return row;
48: }
49: function buildReply(text) {
50:   const match = replyGroups.find((group) => group.match.test(text));
51:   if (match) return match.replies[Math.floor(Math.random() * match.replies.length)];
