:root{--ink:#302d40;--muted:#9290a3;--purple:#8e7bf0;--purple-dark:#7764dc;--line:#efedf5;--paper:#fff;--bg:#f8f7fb;--mint:#dff5e7}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font-family:'DM Sans','Noto Sans SC',sans-serif;font-size:14px;-webkit-font-smoothing:antialiased}
button,a,textarea{font:inherit}
button{color:inherit}
.app-shell{min-height:100vh;display:flex}
.sidebar{width:242px;background:#fff;border-right:1px solid #eeecf3;padding:25px 16px 16px;display:flex;flex-direction:column;flex-shrink:0}
.brand{display:flex;align-items:center;gap:10px;margin:0 12px 43px;text-decoration:none;color:var(--ink)}
.brand-mark,.mini-mori{display:grid;place-items:center;background:linear-gradient(145deg,#a390ff,#7867e3);color:#fff;font-family:'DM Sans',sans-serif;font-weight:700;box-shadow:0 5px 12px #9685eb44}
.brand-mark{width:34px;height:34px;border-radius:12px;font-size:23px;line-height:1}
.brand-name{font-weight:700;font-size:22px;letter-spacing:-1.1px}
.brand-name span{color:#9583ef}
.side-label{padding:0 12px;color:#a6a4b2;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
.main-nav{display:grid;gap:5px;margin-top:12px}
.nav-item{height:42px;width:100%;display:flex;align-items:center;gap:12px;text-align:left;border:0;background:transparent;border-radius:10px;padding:0 12px;color:#777487;cursor:pointer;transition:.18s}
.nav-item:hover,.recent:hover{background:#f8f7fc}
.nav-item.active{color:#705fd0;background:#f2efff;font-weight:600}
.nav-icon{font-size:16px;width:17px;text-align:center}
.nav-dot{margin-left:auto;width:6px;height:6px;border-radius:50%;background:#9583ef}
.side-label-spaced{margin-top:37px;display:flex;justify-content:space-between;align-items:center}
.tiny-plus{border:0;background:none;color:#9e9baa;font-size:18px;line-height:1;cursor:pointer}
.recent-list{margin-top:12px;display:grid;gap:2px}
.recent{border:0;background:transparent;height:37px;border-radius:9px;text-align:left;padding:0 12px;display:flex;align-items:center;gap:10px;color:#858293;font-size:12px;cursor:pointer}
.recent.active{color:#504c62;background:#faf9fd}
.recent-bullet{height:6px;width:6px;border:1.5px solid #bcb8c9;border-radius:50%}
.sidebar-bottom{margin-top:auto}
.upgrade-card{background:linear-gradient(140deg,#f5f1ff,#f9f7ff 72%,#eeebff);border:1px solid #efebff;border-radius:14px;padding:15px 13px 13px;position:relative;overflow:hidden}
.upgrade-card:after{content:'✦';position:absolute;right:13px;top:10px;color:#d0c8ff;font-size:21px}
.upgrade-sparkle{color:#8f7ae7;font-size:17px;margin-bottom:8px}
.upgrade-card strong{font-size:12px}
.upgrade-card p{color:#9995aa;font-size:10px;margin:6px 0 11px}
.upgrade-card button{border:0;background:#fff;border-radius:8px;color:#7967d4;font-size:10px;font-weight:600;padding:8px 9px;width:100%;text-align:left;cursor:pointer}
.upgrade-card button span{float:right}
.profile{display:flex;align-items:center;gap:10px;width:100%;margin-top:16px;padding:12px 5px 2px;background:none;border:0;border-top:1px solid #f1eff5;text-align:left;cursor:pointer}
.profile-avatar,.top-avatar{display:grid;place-items:center;background:#f3e7d8;color:#98775a;border-radius:50%;font-weight:600}
.profile-avatar{width:34px;height:34px;font-size:13px}
.profile-info{display:grid;gap:3px}
.profile-info strong{font-size:12px}
.profile-info small{color:#a09eab;font-size:10px}
.profile-more{margin-left:auto;color:#aaa7b4;font-size:18px}
.main-content{min-width:0;flex:1;display:flex;flex-direction:column}
.topbar{height:70px;border-bottom:1px solid #eeecf3;display:flex;align-items:center;justify-content:space-between;padding:0 38px;background:#fff}
.breadcrumb{display:flex;align-items:center;gap:10px;color:#aaa8b5;font-size:12px}
.breadcrumb strong{color:#514e60;font-weight:600}
.crumb-slash{color:#d0ced8}
.top-actions{display:flex;align-items:center;gap:18px}
.online-status{font-size:11px;color:#9996a9;display:flex;align-items:center;gap:7px}
.online-status i,.scene-footer i{width:7px;height:7px;border-radius:50%;background:#75d99b;box-shadow:0 0 0 3px #75d99b20}
.icon-button{width:30px;height:30px;border:0;background:transparent;color:#9f9cae;font-size:16px;cursor:pointer}
.top-avatar{width:29px;height:29px;border:2px solid #fff;box-shadow:0 0 0 1px #e9e3da;font-size:11px}
.workspace{flex:1;display:grid;grid-template-columns:minmax(350px, .91fr) minmax(470px,1.09fr);gap:22px;padding:22px 30px 24px;min-height:650px;max-width:1450px;width:100%;margin:0 auto}
.companion-panel{border-radius:20px;position:relative;overflow:hidden;min-height:620px;background:linear-gradient(164deg,#f3efff 0%,#ebe8fa 46%,#eeedf8 100%);display:flex;flex-direction:column;align-items:center;isolation:isolate}
.companion-panel:before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 53% 45%,#fff9 0%,#fff0 54%),linear-gradient(0deg,#e4e0f6aa,transparent 35%);z-index:-1}
.scene-glow{position:absolute;width:380px;height:390px;border-radius:50%;background:#ffffff80;filter:blur(55px);top:100px;left:50%;transform:translateX(-50%);z-index:-1}
.scene-orbit{position:absolute;border:1px solid #fff9;border-radius:50%;left:50%;top:48%;transform:translate(-50%,-50%);pointer-events:none}
.orbit-one{width:360px;height:360px}
.orbit-two{width:450px;height:450px;border-color:#fff5}
.weather-pill{position:absolute;left:22px;top:21px;background:#ffffffb8;border:1px solid #fff;border-radius:30px;padding:8px 12px;color:#858196;font-size:10px;display:flex;align-items:center;gap:6px;box-shadow:0 4px 15px #8f83ba0d}
.weather-pill>span:first-child{color:#edb747;font-size:13px}
.weather-divider{width:1px;height:12px;background:#dedbe9;margin:0 2px}
.character-wrap{position:relative;width:275px;height:315px;margin-top:101px;cursor:pointer;outline:none;animation:float 3.8s ease-in-out infinite}
.character-shadow{position:absolute;width:150px;height:24px;left:64px;bottom:2px;border-radius:50%;background:#8275aa30;filter:blur(7px);animation:shadow 3.8s ease-in-out infinite}
.character{position:absolute;width:100%;height:100%;top:0;left:0;transform-origin:50% 85%;transition:transform .35s}
.character-wrap:hover .character{transform:rotate(-3deg) scale(1.025)}
.character-wrap:active .character{transform:scale(.97) rotate(4deg)}
.hair-back{position:absolute;z-index:1;left:64px;top:15px;width:150px;height:146px;border-radius:49% 49% 43% 46%;background:linear-gradient(125deg,#4c426d,#73628e 70%,#51476d);box-shadow:inset -13px -4px 0 #453b62}
.face{position:absolute;z-index:3;left:78px;top:29px;width:122px;height:132px;border-radius:47% 47% 48% 48%;background:linear-gradient(145deg,#ffe6d7,#f8cbb7 85%);box-shadow:inset -7px -4px 0 #efb9a8}
.ear{position:absolute;top:66px;width:19px;height:25px;border-radius:50%;background:#f7c9b8;z-index:-1}
.ear.left{left:-10px}
.ear.right{right:-10px}
.body{position:absolute;z-index:2;left:45px;top:145px;width:190px;height:153px;border-radius:73px 73px 35px 35px;background:linear-gradient(140deg,#b6a7fa,#9384e2 65%,#8273d1);box-shadow:inset 13px 0 20px #fff3,inset -12px -10px 24px #7465c444;overflow:hidden}
.body:before{content:'';position:absolute;left:34px;top:-20px;width:122px;height:82px;border:7px solid #ddd6ff;border-bottom:0;border-radius:70px 70px 0 0;opacity:.72}
.body-shine{position:absolute;width:75px;height:130px;border-radius:50%;left:20px;top:18px;background:linear-gradient(90deg,#ffffff22,transparent)}
.neck{position:absolute;z-index:2;left:124px;top:132px;width:36px;height:31px;background:#f5c5b2}
.collar{position:absolute;top:11px;left:64px;width:62px;height:28px;border-radius:0 0 50% 50%;background:#e8e1ff}
.hood-string{position:absolute;z-index:1;top:42px;width:3px;height:35px;background:#eeeaff;border-radius:3px}
.hood-string.left{left:76px}
.hood-string.right{right:76px}
.hair-fringe{position:absolute;top:-6px;left:3px;width:117px;height:56px;background:linear-gradient(140deg,#66587f,#51466e);border-radius:54% 46% 43% 17%;clip-path:polygon(0 0,100% 0,100% 69%,81% 58%,71% 100%,56% 61%,46% 86%,33% 60%,18% 82%,12% 54%,0 66%)}
.eye{position:absolute;top:75px;width:12px;height:16px;border-radius:50%;background:#493f50;box-shadow:inset 2px 2px 0 #fff;z-index:4}
.eye-left{left:32px}
.eye-right{right:32px}
.eye i{position:absolute;right:1px;top:2px;width:4px;height:5px;background:#fff;border-radius:50%}
.blush{position:absolute;top:94px;width:20px;height:9px;border-radius:50%;background:#ef9c9b70;filter:blur(3px)}
.blush-left{left:14px}
.blush-right{right:14px}
.nose{position:absolute;left:59px;top:95px;width:5px;height:4px;border-radius:50%;background:#de9f91}
.mouth{position:absolute;left:54px;top:107px;width:14px;height:8px;border-bottom:2px solid #a85f6e;border-radius:0 0 50% 50%;z-index:4}
.hair-lock{position:absolute;top:46px;width:22px;height:69px;background:linear-gradient(90deg,#56496e,#75658e);z-index:3}
.lock-left{left:-2px;border-radius:2px 20px 14px 14px;transform:rotate(5deg)}
.lock-right{right:-3px;border-radius:20px 2px 14px 14px;transform:rotate(-5deg)}
.arm{position:absolute;z-index:4;width:39px;height:82px;top:168px;background:linear-gradient(130deg,#f7cfbc,#eeb9ac);border-radius:24px;transform-origin:top center}
.arm-left{left:37px;transform:rotate(31deg)}
.arm-right{right:34px;transform:rotate(-26deg)}
.sparkle{position:absolute;color:#fff;font-size:21px;text-shadow:0 0 12px #fff;z-index:6}
.sparkle-a{right:18px;top:83px;animation:twinkle 2s infinite}
.sparkle-b{left:26px;top:116px;font-size:16px;animation:twinkle 2.4s .5s infinite}
.tap-hint{position:absolute;bottom:0;left:50%;transform:translateX(-50%);font-size:10px;color:#9c94bb;background:#ffffff80;border-radius:20px;padding:5px 11px;opacity:.8}
.character-caption{z-index:1;text-align:center;margin-top:5px}
.name-line{display:flex;justify-content:center;align-items:center;gap:9px}
.name-line h1{font-size:23px;letter-spacing:-.7px;margin:0;font-weight:700;color:#413b58}
.level-tag{color:#8472da;background:#ffffffb0;border:1px solid #fff;border-radius:6px;padding:3px 6px;font-size:9px;font-weight:700}
.character-caption p{font-size:11px;color:#9691a9;margin:5px 0}
.caption-dot{color:#b4a9e3;padding:0 3px}
.mood-card{width:calc(100% - 44px);max-width:390px;margin-top:22px;padding:13px 15px;background:#ffffff91;border:1px solid #ffffffbd;border-radius:14px;box-shadow:0 6px 20px #756ba012}
.mood-top{display:flex;justify-content:space-between;color:#a19caf;font-size:10px}
.mood-top button{border:0;background:none;color:#a29bb8;cursor:pointer;font-size:15px}
.mood-content{display:flex;align-items:center;gap:11px;margin-top:8px}
.mood-emoji{width:33px;height:33px;border-radius:11px;background:#f5f0ff;display:grid;place-items:center;font-size:18px}
.mood-content strong,.mood-content small{display:block}
.mood-content strong{font-size:11px;color:#514c63}
.mood-content small{font-size:9px;color:#a19daf;margin-top:3px}
.mood-wave{margin-left:auto;color:#a99ce8;font-size:23px}
.scene-footer{position:absolute;bottom:18px;left:23px;right:23px;display:flex;align-items:center;justify-content:space-between;color:#aaa5bc;font-size:9px}
.scene-footer span:first-child{display:flex;align-items:center;gap:7px}
.scene-footer i{width:6px;height:6px}
.footer-sparkle{color:#b3a5ed}
.chat-panel{background:#fff;border:1px solid #eeecf3;border-radius:20px;min-height:620px;display:flex;flex-direction:column;box-shadow:0 8px 28px #34304e06;overflow:hidden}
.chat-heading{padding:25px 26px 18px;display:flex;align-items:flex-start;justify-content:space-between}
.chat-title-line{display:flex;align-items:center;gap:9px}
.mini-mori{width:27px;height:27px;border-radius:9px;font-size:18px}
.chat-heading h2{margin:0;font-size:15px;letter-spacing:-.2px}
.beta-tag{font-size:8px;letter-spacing:.06em;font-weight:700;color:#9380e6;background:#f3efff;border-radius:4px;padding:3px 5px}
.chat-heading p{margin:7px 0 0 36px;color:#aaa7b5;font-size:10px}
.more-button{width:30px;height:30px;border:0;border-radius:9px;background:#faf9fc;color:#a5a2b1;font-size:18px;line-height:1;cursor:pointer}
.chat-date{display:flex;align-items:center;gap:10px;margin:0 26px;color:#b1aebb;font-size:9px}
.chat-date span{height:1px;background:#f0eef4;flex:1}
.messages{flex:1;padding:22px 26px 14px;overflow-y:auto;min-height:300px;max-height:calc(100vh - 360px);scrollbar-width:thin;scrollbar-color:#e4e0ef transparent}
.message-row{display:flex;align-items:flex-start;gap:10px;margin:0 0 14px}
.message-avatar{flex-shrink:0;display:grid;place-items:center;width:25px;height:25px;border-radius:9px;background:linear-gradient(145deg,#a390ff,#7867e3);color:#fff;font-size:16px;font-weight:700}
.message-content{max-width:min(90%,400px)}
.message-author{display:flex;align-items:center;gap:8px;font-size:10px;font-weight:600;color:#686477;margin:1px 0 7px}
.message-author time{font-weight:400;font-size:9px;color:#b2afbd}
.bubble{background:#f7f6fa;color:#625f70;border-radius:3px 13px 13px 13px;padding:11px 13px;font-size:11px;line-height:1.85;white-space:pre-wrap}
.message-reactions{display:flex;gap:6px;margin-top:6px}
.reaction{border:1px solid #eeecf2;color:#aaa6b5;border-radius:6px;background:#fff;width:24px;height:20px;cursor:pointer;font-size:11px}
.reaction.liked{color:#ed8e9b;background:#fff2f4;border-color:#ffe1e7}
.user-row{justify-content:flex-end}
.user-row .message-content{display:flex;flex-direction:column;align-items:flex-end}
.user-row .message-author{flex-direction:row-reverse}
.user-row .bubble{background:#8c79e9;color:#fff;border-radius:13px 3px 13px 13px}
.user-row .message-avatar{order:2;background:#f3e7d8;color:#98775a}
.typing-bubble{display:flex;gap:4px;align-items:center;min-height:35px}
.typing-bubble i{width:5px;height:5px;border-radius:50%;background:#a69abf;animation:typing 1s infinite}
.typing-bubble i:nth-child(2){animation-delay:.15s}
.typing-bubble i:nth-child(3){animation-delay:.3s}
.suggestion-row{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin:15px 0 0 35px}
.suggestion-label{width:100%;font-size:9px;color:#aaa7b5;margin-bottom:1px}
.suggestion{background:#fff;border:1px solid #eeecf3;border-radius:20px;padding:7px 10px;color:#807b8e;font-size:9px;white-space:nowrap;cursor:pointer;transition:.2s}
.suggestion:hover{border-color:#d6cef9;background:#f9f7ff;color:#7968d7;transform:translateY(-1px)}
.composer-area{margin:0 18px 15px;border:1px solid #eae8f0;border-radius:13px;background:#fff;box-shadow:0 3px 12px #332c4b08}
.composer-tools{height:39px;display:flex;align-items:center;gap:8px;padding:0 10px}
.tool-button{border:0;background:transparent;color:#a4a1b0;cursor:pointer;height:26px;min-width:25px;padding:0 5px;font-size:15px;border-radius:6px}
.tool-button:hover{background:#f6f4fb;color:#8773e2}
.composer-hint{color:#c0bdc9;font-size:9px}
.tone-button{margin-left:auto;display:flex;align-items:center;gap:5px;font-size:10px;color:#958fbc}
.tone-button .chevron{color:#aaa7b5;font-size:13px}
.composer{display:flex;align-items:flex-end;gap:8px;padding:0 10px 9px}
.composer textarea{resize:none;flex:1;max-height:96px;min-height:31px;outline:none;border:0;padding:7px 2px;color:#514e5e;font-size:11px;line-height:1.6;background:transparent}
.composer textarea::placeholder{color:#c2bfcb}
.send-button{height:29px;width:29px;border:0;border-radius:9px;background:#8b78e9;color:#fff;font-size:18px;line-height:1;cursor:pointer;transition:.2s;box-shadow:0 4px 9px #8b78e940}
.send-button:hover{background:#7462db;transform:translateY(-1px)}
.composer-foot{display:flex;justify-content:space-between;padding:0 2px;margin:0 18px 12px;color:#b4b1bd;font-size:8px}
.composer-foot kbd{font:inherit;background:#f4f3f7;border:1px solid #e9e7ef;border-radius:3px;padding:2px 4px;color:#9692a2}
.composer-foot b{font-weight:400;padding:0 3px}
.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,12px);opacity:0;pointer-events:none;background:#383448;color:#fff;padding:10px 15px;border-radius:10px;box-shadow:0 8px 24px #28233822;font-size:11px;transition:.25s;z-index:10}
.toast.show{transform:translate(-50%,0);opacity:1}
.nav-item,.recent{transition:background .18s,color .18s}
@keyframes float{0%,100%{transform:translateY(0)}
50%{transform:translateY(-9px)}
@keyframes shadow{0%,100%{transform:scale(1);opacity:.75}
50%{transform:scale(.88);opacity:.45}
@keyframes twinkle{0%,100%{opacity:.55;transform:scale(.8) rotate(0)}
50%{opacity:1;transform:scale(1.15) rotate(15deg)}
@keyframes typing{0%,60%,100%{opacity:.35;transform:translateY(0)}
30%{opacity:1;transform:translateY(-4px)}
@media(min-height:900px){.workspace{padding-top:30px;padding-bottom:30px}
.companion-panel,.chat-panel{min-height:700px}
.character-wrap{margin-top:128px;transform:scale(1.08);margin-bottom:20px}
.messages{max-height:calc(100vh - 390px)}
