.chat-heading{padding:22px 20px 16px}
.messages{padding-left:20px;padding-right:20px}
@media(max-width:800px){.sidebar{width:64px;padding:20px 9px 12px;align-items:center}
.brand{margin:0 0 38px}
.brand-name,.side-label,.nav-item>span:not(.nav-icon),.recent-list,.upgrade-card,.profile-info,.profile-more{display:none}
.main-nav{width:100%}
.nav-item{justify-content:center;padding:0;height:42px}
.nav-icon{font-size:19px}
.nav-dot{position:absolute;margin:0 0 25px 25px}
.sidebar-bottom{width:100%}
.profile{justify-content:center;padding:12px 0 2px}
.topbar{height:60px;padding:0 16px}
.workspace{grid-template-columns:1fr;padding:12px;gap:12px}
.companion-panel{min-height:460px;order:1}
.chat-panel{min-height:650px;order:2}
.character-wrap{margin-top:85px;margin-bottom:-10px;transform:scale(.86)}
.mood-card{margin-top:9px}
.scene-footer{bottom:14px}
.messages{max-height:360px}
.chat-heading{padding:20px}
.chat-date{margin:0 20px}
.composer-foot{font-size:7px}
@media(max-width:480px){.sidebar{width:54px;padding:16px 6px 10px}
.brand-mark{width:32px;height:32px}
.top-actions{gap:9px}
.online-status{font-size:0}
.online-status i{width:8px;height:8px}
.breadcrumb{gap:6px;font-size:10px}
.workspace{padding:9px;gap:9px}
.companion-panel{min-height:430px}
.chat-panel{min-height:620px}
.weather-pill{top:14px;left:12px;font-size:9px;padding:7px 9px}
.character-wrap{margin-top:78px}
