.chat-heading{padding:17px 15px 14px}
.chat-heading p{font-size:9px;margin-left:35px}
.messages{padding:18px 14px 12px}
.suggestion-row{margin-left:0;gap:5px}
.suggestion{font-size:8px}
.composer-area{margin:0 10px 12px}
.composer-foot{margin:0 11px 10px;display:grid;gap:5px}
.composer-foot span:last-child{text-align:right}
.message-content{max-width:88%}

