import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

const canvas = document.querySelector('#avatarCanvas');
const wrap = document.querySelector('#character');
const status = document.querySelector('#avatarStatus');
const fallback = document.querySelector('#avatarFallback');

if (canvas && wrap && status) {
  let renderer;
  let frameId;

  const setStatus = (message) => {
    status.textContent = message;
    status.dataset.state = message.includes('失败') ? 'error' : 'ready';
  };

  try {
    renderer = new THREE.WebGLRenderer({
      canvas,
      alpha: true,
      antialias: true,
      powerPreference: 'low-power',
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(28, 1, 0.01, 100);
    scene.add(new THREE.HemisphereLight(0xe9e5ff, 0x7d6680, 2.1));

    const keyLight = new THREE.DirectionalLight(0xfff3e8, 3.2);
    keyLight.position.set(-3, 5, 6);
    scene.add(keyLight);

    const fillLight = new THREE.DirectionalLight(0xc8c3ff, 1.6);
    fillLight.position.set(4, 2, -3);
    scene.add(fillLight);

    const loader = new GLTFLoader();
    loader.load(
      './public/models/mori.glb',
      ({ scene: model, animations }) => {
        scene.add(model);
        model.updateWorldMatrix(true, true);

        const bounds = new THREE.Box3().setFromObject(model);
        if (bounds.isEmpty()) throw new Error('模型没有可显示的几何体');
        const center = bounds.getCenter(new THREE.Vector3());
        const size = bounds.getSize(new THREE.Vector3());
        model.position.sub(center);
        model.rotation.y = 0.12;

        const mixer = new THREE.AnimationMixer(model);
        const usableClips = animations.filter((clip) => clip.duration > 0);
        const idleClip = usableClips.find((clip) => /idle|stand|breath/i.test(clip.name)) || usableClips[0];
        if (idleClip) {
          mixer.clipAction(idleClip).setLoop(THREE.LoopRepeat, Infinity).reset().play();
        }

        let headBone;
        model.traverse((object) => {
          if (object.isBone && /head/i.test(object.name) && !headBone) headBone = object;
        });
        if (!headBone) {
          model.traverse((object) => {
            if (object.isBone && /neck/i.test(object.name) && !headBone) headBone = object;
          });
        }

        const fitCamera = () => {
          const width = Math.max(1, canvas.clientWidth);
          const height = Math.max(1, canvas.clientHeight);
          renderer.setSize(width, height, false);
          camera.aspect = width / height;
          camera.updateProjectionMatrix();

          const verticalDistance = size.y / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)));
          const horizontalDistance = size.x / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * camera.aspect);
          const distance = Math.max(verticalDistance, horizontalDistance, size.z) * 1.19;
          camera.position.set(distance * 0.045, size.y * 0.035, distance);
          camera.near = Math.max(size.y / 1000, 0.001);
          camera.far = Math.max(distance * 20, 100);
          camera.lookAt(0, 0, 0);
          camera.updateProjectionMatrix();
        };

        fitCamera();
        const resizeObserver = new ResizeObserver(fitCamera);
        resizeObserver.observe(wrap);

        const clock = new THREE.Clock();
        let previousHeadNod = 0;
        let elapsed = 0;
        const render = () => {
          frameId = requestAnimationFrame(render);
          const delta = Math.min(clock.getDelta(), 0.05);
          elapsed += delta;
          if (headBone && previousHeadNod) headBone.rotation.x -= previousHeadNod;
          mixer.update(delta);
          previousHeadNod = 0;
          if (wrap.classList.contains('is-speaking') && headBone) {
            previousHeadNod = Math.sin(elapsed * 12) * 0.045;
            headBone.rotation.x += previousHeadNod;
          }
          renderer.render(scene, camera);
        };

        wrap.classList.add('model-ready');
        fallback.hidden = true;
        setStatus(idleClip ? '3D 形象 · 动画待机' : '3D 形象已就绪');
        render();
      },
      undefined,
      (error) => {
        console.error('Mori 3D model failed to load:', error);
        fallback.hidden = false;
        canvas.hidden = true;
        setStatus('3D 加载失败 · 显示备用形象');
      },
    );
  } catch (error) {
    console.error('Mori 3D renderer could not start:', error);
    fallback.hidden = false;
    canvas.hidden = true;
    setStatus('3D 加载失败 · 显示备用形象');
  }

  window.addEventListener('pagehide', () => {
    if (frameId) cancelAnimationFrame(frameId);
    renderer?.dispose();
  }, { once: true });
}

#avatarCanvas{position:absolute;inset:0;width:100%;height:100%;display:block;z-index:1;pointer-events:none}
#avatarCanvas[hidden]{display:none}
.avatar-status{position:absolute;top:8px;left:50%;z-index:4;transform:translateX(-50%);white-space:nowrap;border:1px solid #ffffffb8;border-radius:999px;background:#ffffffa8;padding:6px 11px;color:#77718f;font-size:10px;font-weight:600;letter-spacing:.01em;box-shadow:0 4px 16px #766a9b12;backdrop-filter:blur(10px);transition:background .2s,color .2s,box-shadow .2s}
.avatar-status[data-state="error"]{color:#8e6682}
.avatar-status[data-state="speaking"]{color:#6654c7;background:#f5f1ffed;box-shadow:0 4px 20px #8e7bf044}
.avatar-status[data-state="speaking"]::after{content:"";display:inline-block;width:19px;height:9px;margin-left:7px;vertical-align:-1px;background:linear-gradient(90deg,transparent 0 8%,#8e7bf0 8% 18%,transparent 18% 29%,#8e7bf0 29% 42%,transparent 42% 53%,#8e7bf0 53% 70%,transparent 70% 81%,#8e7bf0 81% 92%,transparent 92%);animation:speaking-wave .65s ease-in-out infinite alternate}
.character-shadow{z-index:0}
.character{z-index:1}
.tap-hint{z-index:3}
.character-wrap.is-speaking #avatarCanvas{filter:drop-shadow(0 0 13px #9b84f077)}
.character-wrap.is-speaking #avatarFallback{animation:avatar-speaking .42s ease-in-out infinite alternate}
@keyframes speaking-wave{from{transform:scaleY(.5);opacity:.65}to{transform:scaleY(1.15);opacity:1}}
@keyframes avatar-speaking{from{transform:translateY(0) rotate(-.6deg)}to{transform:translateY(-2px) rotate(.6deg)}}
@media(max-width:480px){.avatar-status{top:4px;font-size:9px;padding:5px 9px}}
@media(prefers-reduced-motion:reduce){.character-wrap,.character-shadow,.avatar-status[data-state="speaking"]::after,.character-wrap.is-speaking #avatarFallback{animation:none!important;transition:none!important}}

