input.content:
.workspace > [hidden] { display: none !important; }
.workspace.show-tool-view { display: block; }
.tool-view { min-height: 620px; padding: 38px clamp(22px, 5vw, 64px); border: 1px solid #eeecf3; border-radius: 20px; background: #fff; box-shadow: 0 8px 28px #34304e06; }
.tool-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; margin-bottom: 30px; }
.tool-eyebrow { color: #9c8be5; font-size: 10px; font-weight: 700; letter-spacing: .12em; }
.tool-heading h2, .dialog-heading h2 { margin: 7px 0 8px; color: #302d40; font-size: 25px; letter-spacing: -.5px; }
.tool-heading p { margin: 0; color: #9693a2; font-size: 13px; }
.primary-action, .quiet-action { min-height: 38px; border: 0; border-radius: 10px; padding: 0 16px; font-weight: 600; cursor: pointer; }
.primary-action { color: #fff; background: linear-gradient(135deg, #9b88f5, #7866df); box-shadow: 0 5px 12px #9685eb33; }
.primary-action:hover { filter: brightness(1.04); }
.quiet-action { color: #777487; background: #f7f6fa; }
.note-editor { display: grid; gap: 9px; max-width: 720px; margin: 0 0 25px; padding: 20px; border: 1px solid #eeeaf7; border-radius: 15px; background: #fcfbff; }
.note-editor[hidden] { display: none; }
.note-editor label { margin-top: 5px; color: #777487; font-size: 11px; font-weight: 600; }
.note-editor input, .note-editor textarea, .task-form input { width: 100%; border: 1px solid #eae7f1; border-radius: 9px; padding: 11px 12px; color: #39364a; background: #fff; outline: 0; resize: vertical; }
.note-editor input:focus, .note-editor textarea:focus, .task-form input:focus { border-color: #aa9bf1; box-shadow: 0 0 0 3px #8e7bf018; }
.editor-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 4px; }
.note-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 14px; }
.note-card { min-height: 170px; padding: 17px; border: 1px solid #f0edf5; border-radius: 14px; background: linear-gradient(145deg, #fff, #fcfbff); }
.note-card-top { display: flex; align-items: center; justify-content: space-between; color: #a38fe9; font-size: 10px; font-weight: 600; }
.note-card-top button, .task-item > button { border: 0; background: transparent; color: #aaa6b5; font-size: 20px; cursor: pointer; }
.note-card h3 { margin: 13px 0 7px; color: #484458; font-size: 14px; }
.note-card p { margin: 0 0 14px; color: #777487; font-size: 12px; line-height: 1.8; overflow-wrap: anywhere; }
